123	impl Parse for Meta {
124	    fn parse(input: ParseStream) -> Result<Self> {
125	        Ok(Self {
126	            scope: parse_flag::<kw::scope>(input)?,
127	            contextual: parse_flag::<kw::contextual>(input)?,
128	            name: parse_string::<kw::name>(input)?,
129	            title: parse_string::<kw::title>(input)?,
130	            constructor: parse_flag::<kw::constructor>(input)?,
131	            since: parse_key_value::<kw::since, Since>(input)?,
132	            keywords: parse_string_array::<kw::keywords>(input)?,
133	            parent: parse_key_value::<kw::parent, _>(input)?,
134	        })
135	    }
136	}
