179	/// Parse details about a function parameter.
180	fn parse_param(
181	    special: &mut SpecialParams,
182	    params: &mut Vec<Param>,
183	    parent: Option<&syn::Type>,
184	    input: &syn::FnArg,
185	) -> Result<()> {
186	    let typed = match input {
187	        syn::FnArg::Receiver(recv) => {
188	            let mut binding = Binding::Owned;
189	            if recv.reference.is_some() {
190	                if recv.mutability.is_some() {
191	                    binding = Binding::RefMut;
192	                } else {
193	                    binding = Binding::Ref;
194	                }
195	            }
196	
197	            special.self_ = Some(Param {
198	                binding,
199	                ident: syn::Ident::new("self_", recv.self_token.span),
200	                ty: match parent {
201	                    Some(ty) => ty.clone(),
202	                    None => bail!(recv, "explicit parent type required"),
203	                },
204	                name: "self".into(),
205	                docs: documentation(&recv.attrs),
206	                named: false,
207	                variadic: false,
208	                external: false,
209	                default: None,
210	            });
211	            return Ok(());
212	        }
213	        syn::FnArg::Typed(typed) => typed,
214	    };
215	
216	    let syn::Pat::Ident(syn::PatIdent { by_ref: None, mutability: None, ident, .. }) =
217	        &*typed.pat
218	    else {
219	        bail!(typed.pat, "expected identifier");
220	    };
221	
222	    match ident.to_string().as_str() {
223	        "engine" => special.engine = true,
224	        "context" => special.context = true,
225	        "args" => special.args = true,
226	        "span" => special.span = true,
227	        _ => {
228	            let mut attrs = typed.attrs.clone();
229	            params.push(Param {
230	                binding: Binding::Owned,
231	                ident: ident.clone(),
232	                ty: (*typed.ty).clone(),
233	                name: ident.to_string().to_kebab_case(),
234	                docs: documentation(&attrs),
235	                named: has_attr(&mut attrs, "named"),
236	                variadic: has_attr(&mut attrs, "variadic"),
237	                external: has_attr(&mut attrs, "external"),
238	                default: parse_attr(&mut attrs, "default")?.map(|expr| {
239	                    expr.unwrap_or_else(
240	                        || parse_quote! { ::std::default::Default::default() },
241	                    )
242	                }),
243	            });
244	            validate_attrs(&attrs)?;
245	        }
246	    }
247	
248	    Ok(())
249	}
